 if(path==='login'&&method==='POST'){const ip=request.headers.get('CF-Connecting-IP')||'unknown',cutoff=new Date(Date.now()-10*60*1000).toISOString();await env.DB.prepare('DELETE FROM login_attempts WHERE attempted_at<?').bind(cutoff).run();await env.DB.prepare('DELETE FROM sessions WHERE expires_at<?').bind(now()).run();const attempts=await env.DB.prepare('SELECT COUNT(*) n FROM login_attempts WHERE ip=? AND attempted_at>?').bind(ip,cutoff).first();const d=await body(request),username=String(d.username||'').trim();const nameFailures=username?await env.DB.prepare("SELECT COUNT(*) n FROM audit_log WHERE action='login-failed' AND username=? COLLATE NOCASE AND created_at>?").bind(username,cutoff).first():{n:0};if(attempts.n>=10||nameFailures.n>=20)return fail('Troppi tentativi. Riprova tra qualche minuto.',429);const user=await env.DB.prepare('SELECT * FROM users WHERE username=? COLLATE NOCASE AND active=1').bind(username).first(),ver=user?await verifyPassword(String(d.password||''),user,env):{ok:false};if(!ver.ok){await env.DB.prepare('INSERT INTO login_attempts(ip,attempted_at) VALUES(?,?)').bind(ip,now()).run();await audit(env,{id:'',username:username||'(vuoto)'},'login-failed','account','','IP '+ip);return fail('Credenziali non valide.',401)}if(ver.legacy||!String(user.password_hash).startsWith(HASH_PREFIX))await upgradePassword(user,String(d.password||''),env);await env.DB.prepare('DELETE FROM login_attempts WHERE ip=?').bind(ip).run();await env.DB.prepare('UPDATE users SET last_login=? WHERE id=?').bind(now(),user.id).run();const token=random(32),expires=new Date(Date.now()+7*86400000).toISOString();await env.DB.prepare('INSERT INTO sessions(token_hash,user_id,expires_at) VALUES(?,?,?)').bind(await digest(token),user.id,expires).run();return json({id:user.id,username:user.username,role:user.role},200,{'set-cookie':cookie(token,604800)})}
