 if(path==='me'&&method==='PUT'){const d=await body(request);if(String(d.new_password||'').length<12)return fail('La nuova password deve avere almeno 12 caratteri.');const stored=await env.DB.prepare('SELECT password_hash,password_salt FROM users WHERE id=?').bind(user.id).first();if(!stored||!(await verifyPassword(String(d.current_password||''),stored,env)).ok)return fail('La password attuale non è corretta.',403);const salt=random(16),hash=HASH_PREFIX+await passwordHash(String(d.new_password),salt,activePepper(env)),token=sessionToken(request),tokenHash=token?await digest(token):'';await env.DB.prepare('UPDATE users SET password_hash=?,password_salt=? WHERE id=?').bind(hash,salt,user.id).run();await env.DB.prepare('DELETE FROM sessions WHERE user_id=? AND token_hash<>?').bind(user.id,tokenHash).run();await audit(env,user,'Cambia password','account',user.id,'Password aggiornata dal titolare');return json({ok:true})}
 if(path==='settings'&&method==='GET'){const {results}=await env.DB.prepare("SELECT key,value FROM settings WHERE key IN ('xp_milestone_step','xp_reminder_window','birthday_reminders','last_backup_at')").all(),s=Object.fromEntries(results.map(x=>[x.key,x.value]));return json({xp_milestone_step:Number(s.xp_milestone_step)||5000,xp_reminder_window:Number(s.xp_reminder_window)||750,birthday_reminders:s.birthday_reminders!=='0',last_backup_at:s.last_backup_at||''})}
 if(path==='settings'&&method==='PUT'){if(!admin(user))return fail('Operazione riservata all’amministratore.',403);const d=await body(request),step=Math.max(250,Math.min(100000,Math.round(Number(d.xp_milestone_step)||0))),window=Math.max(0,Math.min(step,Math.round(Number(d.xp_reminder_window)||0))),birthday=d.birthday_reminders?1:0;for(const [key,value] of [['xp_milestone_step',step],['xp_reminder_window',window],['birthday_reminders',birthday]])await env.DB.prepare('INSERT OR REPLACE INTO settings(key,value) VALUES(?,?)').bind(key,String(value)).run();await audit(env,user,'Aggiorna promemoria','impostazioni','xp',`${step} XP · finestra ${window} XP`);return json({ok:true})}
 if(path==='players'&&method==='GET'){const {results}=await env.DB.prepare('SELECT * FROM players WHERE active=1 ORDER BY name COLLATE NOCASE').all();return json(results)}
