 if(path==='player-notes'&&method==='POST'){if(!canEdit(user))return fail('Solo editor e amministratori possono scrivere note sui PG.',403);const d=await body(request),playerId=String(d.player_id||''),text=String(d.body||'').trim();if(!playerId)return fail('Scegli il PG a cui si riferisce la nota.');if(text.length<2)return fail('Scrivi il testo della nota.');if(text.length>6000)return fail('La nota può avere al massimo 6000 caratteri.');const pg=await env.DB.prepare('SELECT id,name FROM players WHERE id=?').bind(playerId).first();if(!pg)return fail('PG non trovato.',404);const nid=id(),stamp=now();await env.DB.prepare('INSERT INTO player_notes(id,player_id,body,created_by,created_at,updated_at) VALUES(?,?,?,?,?,?)').bind(nid,playerId,text,user.username,stamp,stamp).run();await audit(env,user,'Scrive una nota su un PG','PG',playerId,pg.name+' · '+text.slice(0,120));return json({id:nid},201)}
