 if(path==='sessions'&&method==='POST'){if(!canEdit(user))return fail('Solo editor e amministratori possono registrare sessioni.',403);const d=await body(request),date=String(d.date||''),type=String(d.type||'Principale'),title=String(d.title||'').trim(),participants=Array.isArray(d.participants)?d.participants:[];if(!validDate(date)||!title||!participants.length||participants.length>100)return fail('Inserisci data, avventura e almeno un partecipante.');const picked=new Set(),batch=[];for(const row of participants){const p=await env.DB.prepare('SELECT id,name FROM players WHERE id=? AND active=1').bind(row.player_id).first();if(!p)return fail('Uno dei PG selezionati non è disponibile.');const xpRow=xpValue(row.xp);if(xpRow<0){const cur=await env.DB.prepare('SELECT COALESCE(SUM(xp),0) AS t FROM xp_entries WHERE player_id=?').bind(p.id).first();if(Number(cur.t)+xpRow<0)return fail('Il totale XP di '+p.name+' non può scendere sotto 0 XP.',400)}if(picked.has(p.id))continue;picked.add(p.id);batch.push(env.DB.prepare('INSERT INTO xp_entries(id,player_id,player_name,date,type,title,xp,notes,created_by) VALUES(?,?,?,?,?,?,?,?,?)').bind(id(),p.id,p.name,date,type,title,xpValue(row.xp),String(row.notes||''),user.username))}if(!batch.length)return fail('Seleziona almeno un partecipante.');batch.push(env.DB.prepare('INSERT INTO adventure_details(date,type,title,summary,location,gp,items,fame,gp_amount,gp_per,updated_by,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(date,type,title) DO UPDATE SET summary=excluded.summary,location=excluded.location,gp=excluded.gp,items=excluded.items,fame=excluded.fame,gp_amount=excluded.gp_amount,gp_per=excluded.gp_per,updated_by=excluded.updated_by,updated_at=excluded.updated_at').bind(date,type,title,String(d.summary||'').slice(0,12000),String(d.location||'').slice(0,200),String(d.gp||'').slice(0,120),String(d.items||'').slice(0,4000),String(d.fame||'').slice(0,4000),gpNum(d.gp_amount),gpPer(d.gp_per),user.username,now()));await env.DB.batch(batch);await audit(env,user,'Registra sessione','avventura',date+'|'+type+'|'+title,`${batch.length-1} partecipanti · ${title}`);return json({participants:batch.length-1},201)}
 if(path==='sessions'&&method==='DELETE'){if(!canEdit(user))return fail('Solo editor e amministratori possono eliminare sessioni.',403);const q=new URL(request.url).searchParams,date=String(q.get('date')||''),type=String(q.get('type')||''),title=String(q.get('title')||'').trim();if(!validDate(date)||!title)return fail('Indica data, tipo e nome della sessione.',400);const {results}=await env.DB.prepare('SELECT * FROM xp_entries WHERE date=? AND type=? AND title=?').bind(date,type,title).all();if(!results.length)return fail('Sessione non trovata.',404);const adv=await env.DB.prepare('SELECT * FROM adventure_details WHERE date=? AND type=? AND title=?').bind(date,type,title).first(),batch=results.map(e=>env.DB.prepare('INSERT OR REPLACE INTO xp_entry_trash(id,player_id,player_name,date,type,title,xp,notes,created_by,deleted_by,deleted_at) VALUES(?,?,?,?,?,?,?,?,?,?,?)').bind(e.id,e.player_id,e.player_name,e.date,e.type,e.title,e.xp,e.notes,String(e.created_by||''),user.username,now()));batch.push(env.DB.prepare('DELETE FROM xp_entries WHERE date=? AND type=? AND title=?').bind(date,type,title));if(adv)batch.push(env.DB.prepare('INSERT OR REPLACE INTO adventure_trash(id,date,type,title,summary,location,gp,items,fame,gp_amount,gp_per,deleted_by,deleted_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)').bind(id(),adv.date,adv.type,adv.title,adv.summary,adv.location,adv.gp||'',adv.items||'',adv.fame||'',adv.gp_amount||0,adv.gp_per||'',user.username,now()));batch.push(env.DB.prepare('DELETE FROM adventure_details WHERE date=? AND type=? AND title=?').bind(date,type,title));await env.DB.batch(batch);await audit(env,user,'Elimina sessione','avventura',[date,type,title].join('|'),title+' · '+results.length+' voci XP e diario nel cestino');return json({deleted:results.length,diary:!!adv})}
