 const planMatch=path.match(/^session-plans\/([\w-]+)$/);if(planMatch){if(!canEdit(user))return fail('Solo editor e amministratori possono gestire sessioni programmate.',403);const sid=planMatch[1],plan=await env.DB.prepare('SELECT * FROM session_plans WHERE id=?').bind(sid).first();if(!plan)return fail('Sessione programmata non trovata.',404);if(method==='DELETE'){await env.DB.prepare("UPDATE session_plans SET status='cancelled',updated_at=? WHERE id=?").bind(now(),sid).run();await audit(env,user,'Annulla sessione','sessione',sid,plan.title);return json({ok:true})}if(method==='PUT'){const d=await body(request),title=String(d.title||plan.title).trim(),date=String(d.date||plan.date),status=['planned','completed','cancelled'].includes(d.status)?d.status:plan.status;if(!title||!validDate(date))return fail('Inserisci nome e data validi.');await env.DB.prepare('UPDATE session_plans SET title=?,date=?,start_time=?,type=?,location=?,notes=?,status=?,updated_at=? WHERE id=?').bind(title,date,String(d.start_time||plan.start_time||'').slice(0,5),String(d.type||plan.type),String(d.location||''),String(d.notes||''),status,now(),sid).run();if(Array.isArray(d.participants)){const roster=await env.DB.prepare('SELECT id FROM players WHERE active=1').all(),submitted=new Map(d.participants.map(x=>[x.player_id,x]));for(const p of roster.results){const x=submitted.get(p.id)||{},availability=['available','unavailable','maybe'].includes(x.availability)?x.availability:'pending';await env.DB.prepare('INSERT INTO session_participation(session_id,player_id,availability,updated_at) VALUES(?,?,?,?) ON CONFLICT(session_id,player_id) DO UPDATE SET availability=excluded.availability,updated_at=excluded.updated_at').bind(sid,p.id,availability,now()).run()}}await audit(env,user,'Aggiorna sessione programmata','sessione',sid,title+' · '+date);return json({ok:true})}}

