const SHEET_CELLS={name:'C6',klass:'T5',race:'T7',align:'AJ28',level:'F6'};
const SHEET_LABEL={name:'Nome',class:'Classe',race:'Razza',alignment:'Allineamento',level:'Livello'};
const SHEET_CLASS={barbarian:'Barbaro',bard:'Bardo',cleric:'Chierico',druid:'Druido',fighter:'Guerriero',monk:'Monaco',paladin:'Paladino',ranger:'Ranger',rogue:'Ladro',sorcerer:'Stregone',warlock:'Warlock',wizard:'Mago',artificer:'Artefice','blood hunter':'Cacciatore del Sangue'};
